-- Prueba segura (modo seco, no envia ni guarda nada): lanza 6 peticiones a recordatorios-de-nexa leyendo el secreto nuevo desde la base; una lleva un secreto falso y debe responder 401.
select
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"mode":"badge","dry":true}'::jsonb, timeout_milliseconds := 60000) as badge_minima,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"mode":"badge","dry":true,"legacy":true}'::jsonb, timeout_milliseconds := 60000) as badge_vista,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"mode":"unread","dry":true}'::jsonb, timeout_milliseconds := 60000) as unread_minima,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"mode":"unread","dry":true,"legacy":true}'::jsonb, timeout_milliseconds := 60000) as unread_vista,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"slot":"am","dry":true}'::jsonb, timeout_milliseconds := 60000) as diario_minima,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', (select valor from public.nexa_cron_secret where id = 1)), body := '{"slot":"am","dry":true,"legacy":true}'::jsonb, timeout_milliseconds := 60000) as diario_vista,
  net.http_post(url := 'https://znicbyzszdztwyecydbl.supabase.co/functions/v1/recordatorios-de-nexa', headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', 'secreto-falso-de-prueba'), body := '{"mode":"badge","dry":true}'::jsonb, timeout_milliseconds := 60000) as secreto_falso;
